let syms = find_symbols("ptrace");
for s in syms {
  if s.name == "ptrace" || s.name.ends_with("::ptrace") {
    let xrefs = get_xrefs(s.address);
    for x in xrefs {
      report_patch("Caller of " + s.name, x.from, "HIGH", "Calls " + s.name + " via " + x.instruction, "quick", "nop");
    }
  }
}
let prctl_syms = find_symbols("prctl");
for s in prctl_syms {
  if s.name == "prctl" || s.name.ends_with("::prctl") {
    let xrefs = get_xrefs(s.address);
    for x in xrefs {
      report("Caller of " + s.name, x.from, "MEDIUM", "Calls " + s.name + " via " + x.instruction);
    }
  }
}
